// ---- end shared: common ----
const env = $env;
const data = $input.first().json;
const store = $getWorkflowStaticData('global');
store.seenAlerts = store.seenAlerts || {};
const seen = store.seenAlerts;
const now = Date.now();
const windowMs = envInt(env, 'DEDUP_WINDOW_MINUTES', 360, 1, 10080) * 60000;

for (const [k, at] of Object.entries(seen)) if (now - at > windowMs) delete seen[k];

const fresh = [];
const duplicates = [];
for (const a of data.alerts) {
  const key = (a.fingerprint || (a.alert_name + '|' + a.service_name)) + '|' + a.started_at;
  if (seen[key]) { duplicates.push({ alert_name: a.alert_name, service_name: a.service_name, key }); continue; }
  seen[key] = now;
  fresh.push({ ...a, dedup_key: key });
}

return [{
  json: {
    ...data,
    alerts: fresh,
    duplicates,
    response: {
      accepted: true,
      new_alerts: fresh.length,
      duplicate_alerts: duplicates.length,
      resolved_alerts: data.resolved,
      rejected_alerts: data.rejected.length,
      rejected: data.rejected,
    },
  },
}];

// Workflow 01 – Node: "Create incident (backend) – BLOCKED".
// One item per new alert.
//
// BLOCKED: the backend has no machine endpoint that creates an incident from an
// alert. The approved contract (database/API_AND_INTEGRATION_CONTRACTS.md, B.3)
// lists only start/complete, investigations/:id/analysis, recovery-checks and
// incident-events, and none of them creates incidents. Until the backend adds
// one, this node does NOT invent a URL: it passes the alert on with
// incident_id = null and records why, so the investigation can still run and
// be tested. When the endpoint exists, replace this node with
// "Sign request" + "HTTP Request" (see workflow 07 for the pattern).

return $input.first().json.alerts.map((a) => ({
  json: {
    incident_id: null,
    investigation_id: null,
    incident_created: false,
    incident_blocker: 'Backend endpoint for creating an incident from an alert does not exist yet (backend dependency BD-1).',
    alert_name: a.alert_name,
    service_name: a.service_name,
    severity: a.severity,
    started_at: a.started_at,
    summary: a.summary,
    dedup_key: a.dedup_key,
  },
}));

// Workflow 01 – Node: "Intake result". Summarizes what happened to each alert
// (visible in the n8n execution log).
const alerts = $('Create incident (backend) – BLOCKED').all().map((i) => i.json);
return $input.all().map((item, idx) => {
  const rca = item.json || {};
  const a = alerts[idx] || {};
  return {
    json: {
      alert_name: a.alert_name,
      service_name: a.service_name,
      incident_id: a.incident_id,
      incident_created: a.incident_created,
      rca_status: rca.status || (rca.error ? 'workflow_error' : 'unknown'),
      rca_stored: rca.stored === true,
      error: rca.error || null,
    },
  };
});
